using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change #1: Discriminator property renamed from "Discriminator" to "$type".
        // To read existing documents that use the old property name, remap it explicitly.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change #2: The id property no longer prepends the discriminator.
        // Old format: "Blog|1". To keep reading existing documents, opt back in.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id");
        modelBuilder.Entity<Blog>().UseIdProperty(b => b.Id)
            .HasIdValueGenerationStrategy(CosmosIdValueGenerationStrategy.None);

        // EF Core 9 breaking change #3: HasIndex() now throws for the Cosmos provider.
        // Cosmos indexes are managed via indexing policy, not EF model. Removed HasIndex call.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

